<?php
global $wpdb; $q=sanitize_text_field($_GET['q']??''); $rows=[]; if($q!==''){$rows=$wpdb->get_results($wpdb->prepare("SELECT surah_id,ayah_number,arabic_text FROM {$wpdb->prefix}quran_ayahs WHERE MATCH(arabic_text) AGAINST(%s IN NATURAL LANGUAGE MODE) LIMIT 40",$q),ARRAY_A);} ?><!doctype html><html><body><main><h1>Quran Search</h1><form><input name="q" value="<?php echo esc_attr($q); ?>"><button>Search</button></form><?php foreach($rows as $r): ?><p><?php echo esc_html('S'.$r['surah_id'].':'.$r['ayah_number']); ?> — <?php echo esc_html($r['arabic_text']); ?></p><?php endforeach; ?></main></body></html>
